import{_ as a,o as i,c as n,a2 as s}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Sistema de profesiones","description":"","frontmatter":{},"headers":[],"relativePath":"es/game-design/professions/profession-system.md","filePath":"es/game-design/professions/profession-system.md"}'),o={name:"es/game-design/professions/profession-system.md"};function r(t,e,d,c,l,p){return i(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="profession-system" tabindex="-1">Sistema de profesiones <a class="header-anchor" href="#profession-system" aria-label="Enlace permanente a &quot;Sistema de profesiones&quot;">​</a></h1><p><strong>Estado del diseño:</strong> Propuesto; las preguntas abiertas están Sin resolver. Las reglas existentes con estado Aceptado citadas abajo conservan su propio alcance. <strong>Implementación:</strong> este rediseño es solo documentación; este lote no establece una implementación de gameplay. <strong>Disponibilidad:</strong> no establecida para las mecánicas rediseñadas. <strong>Verificación:</strong> revisión de fuentes/documentación, no validación en ejecución. <strong>Revisado:</strong> 2026-10-09 para la versión pública; se conservan el estado del diseño y las mecánicas de la especificación canónica.</p><p><a href="/Syrolands-Public/es/guide/professions/overview.html">Resumen para jugadores</a> · <a href="/Syrolands-Public/es/game-design/professions/profession-system.html">Sistema de profesiones</a></p><h2 id="philosophy-and-scope" tabindex="-1">Filosofía y alcance <a class="header-anchor" href="#philosophy-and-scope" aria-label="Enlace permanente a &quot;Filosofía y alcance&quot;">​</a></h2><p><strong>No hay personajes artesanos; hay personajes que conocen oficios.</strong> El sistema propuesto aborda los personajes alternativos artesanos limitados al taller haciendo útiles las profesiones dentro del mismo límite global de habilidades que otras capacidades del personaje. No prohíbe personajes alternativos ni exige que toda profesión conceda bonificaciones de combate.</p><p>La fabricación debería contribuir a la aventura cotidiana, PvM, PvP cuando corresponda, supervivencia, exploración, economía, conocimiento de materiales, mantenimiento e interacción con el mundo. Una profesión combina generalmente producción, utilidad en expediciones, afinidad con equipo/materiales, utilidad justificada en combate o supervivencia, conocimiento, economía/reputación y descubrimiento. Las mejoras planas de combate no pueden sustituir esa identidad.</p><p>Esta página define descubrimiento artesanal, diarios, intercambio de conocimiento, producción y encargos. <a href="/Syrolands-Public/es/game-design/characters/progression.html">Progresión del personaje</a>, <a href="/Syrolands-Public/es/game-design/characters/skills-and-skillcap.html">Habilidades y límite</a> y <a href="/Syrolands-Public/es/game-design/characters/techniques-and-specialization.html">Técnicas y especialización</a> definen ahora el marco compartido del personaje. Cada página profesional define su ciclo específico; <a href="/Syrolands-Public/es/game-design/items/itemization-and-craft-quality.html">Objetos y calidad artesanal</a>, la calidad de objetos fabricados y de botín. Son lugares canónicos para propuestas, no mecánicas nuevas con estado Aceptado ni permiso para implementarlas.</p><h2 id="skill-technique-profession-and-identity" tabindex="-1">Habilidad, técnica, profesión e identidad <a class="header-anchor" href="#skill-technique-profession-and-identity" aria-label="Enlace permanente a &quot;Habilidad, técnica, profesión e identidad&quot;">​</a></h2><p>La <a href="/Syrolands-Public/es/game-design/characters/techniques-and-specialization.html#skill-learned-knowledge-and-identity">jerarquía compartida de técnicas e identidad</a> define ahora este principio de Batch 01: habilidad amplia, técnica concreta aprendida, camino profesional práctico y reputación individual en el mundo. Un carpintero competente no conoce automáticamente <a href="/Syrolands-Public/es/game-design/professions/carpentry.html#bowmaking-and-fletching">Bowmaking</a>; el conocimiento artesanal raro sigue aprendiéndose por separado.</p><h2 id="entry-skill-cap-and-progression" tabindex="-1">Inicio, límite de habilidades y progresión <a class="header-anchor" href="#entry-skill-cap-and-progression" aria-label="Enlace permanente a &quot;Inicio, límite de habilidades y progresión&quot;">​</a></h2><p><a href="/Syrolands-Public/es/game-design/characters/skills-and-skillcap.html">Habilidades y límite</a> define el límite común, aumento, franjas de capacidad y dirección de maestros. <a href="/Syrolands-Public/es/game-design/characters/character-creation.html">Creación de personajes</a> define competencias iniciales. Mantienen estado Propuesto y no cambian la configuración.</p><p>Batch 02 precisa la franja de aumento 80–90 de «Lento» de Batch 01 a <strong>«Muy lento»</strong>. La última propuesta se centraliza en la <a href="/Syrolands-Public/es/game-design/characters/skills-and-skillcap.html#desired-skill-gain">tabla de aumento</a>; la fuente conservada de Batch 01 mantiene su redacción original. Es una revisión explícita de propuesta, no balance Aceptado. El ancla existente de la sección sigue siendo válida.</p><h2 id="skill-knowledge-and-human-mastery" tabindex="-1">Habilidad, conocimiento y maestría humana <a class="header-anchor" href="#skill-knowledge-and-human-mastery" aria-label="Enlace permanente a &quot;Habilidad, conocimiento y maestría humana&quot;">​</a></h2><p>El <a href="/Syrolands-Public/es/game-design/characters/progression.html#character-skill-knowledge-and-player-mastery">modelo compartido de tres ejes</a> define este principio: la habilidad determina la capacidad, el conocimiento determina posibilidades/información y la maestría humana determina el rendimiento. Los diarios artesanales y procesos aprendidos aplican ese modelo; una habilidad de 100 no los completa.</p><h2 id="character-journals-and-discovery" tabindex="-1">Diarios del personaje y descubrimiento <a class="header-anchor" href="#character-journals-and-discovery" aria-label="Enlace permanente a &quot;Diarios del personaje y descubrimiento&quot;">​</a></h2><p>El conocimiento debería persistir por personaje. Los diarios candidatos son:</p><table tabindex="0"><thead><tr><th>Profesión</th><th>Registro de conocimiento</th></tr></thead><tbody><tr><td>Cooking</td><td>Culinary Journal / Taste Codex</td></tr><tr><td>Alchemy</td><td>Alchemical Journal</td></tr><tr><td>Mining</td><td>Geological Journal</td></tr><tr><td>Blacksmithing</td><td>Metallurgical Journal</td></tr><tr><td>Tailoring</td><td>Material/Tailoring Journal</td></tr><tr><td>Lumberjacking</td><td>Forester&#39;s Journal</td></tr><tr><td>Carpentry</td><td>Woodworker&#39;s Journal</td></tr><tr><td>Tinkering</td><td>Mechanist&#39;s Journal</td></tr></tbody></table><p>Exploración, experimentación, maestros, libros/manuscritos, misiones/desafíos, gremios/academias, ingeniería inversa, materiales inusuales, resultados observados y otros jugadores donde se permita pueden aportar conocimiento. Preferir <strong>observaciones → comprensión → técnica/fórmula aprendida</strong> a una sucesión de avisos de recetas desbloqueadas. Qué puede compartirse y qué pasos requieren experiencia personal sigue sin resolverse.</p><h2 id="sharing-knowledge-and-keeping-secrets" tabindex="-1">Compartir conocimiento y guardar secretos <a class="header-anchor" href="#sharing-knowledge-and-keeping-secrets" aria-label="Enlace permanente a &quot;Compartir conocimiento y guardar secretos&quot;">​</a></h2><p><strong>El conocimiento puede compartirse; la maestría no puede copiarse.</strong> Se esperan conversaciones externas y wikis, no son algo que impedir. Principios estables del mundo coexisten con variación de materiales, procedencia y calidad, intervalos eficaces de proceso, respuesta cualitativa/perceptiva, habilidad personal y técnicas aprendidas. Un único número mágico publicado no debería reproducir todo resultado.</p><p>La ingeniería inversa proporciona pistas, no fórmulas completas. Procedimientos privados, fuentes materiales inusuales, consistencia difícil, enseñanza parcial y técnicas raras pueden sostener secretos. Evitar leyes físicas arbitrarias por personaje. Pequeñas afinidades personales o diferencias interpretativas son únicamente candidatos futuros opcionales si se justifican; no son el mecanismo principal contra las wikis.</p><h2 id="manual-discovery-and-batch-production" tabindex="-1">Descubrimiento manual y producción por lotes <a class="header-anchor" href="#manual-discovery-and-batch-production" aria-label="Enlace permanente a &quot;Descubrimiento manual y producción por lotes&quot;">​</a></h2><p><strong>La ejecución manual establece la maestría; la producción por lotes convierte esa maestría en escala económica.</strong> Descubrimiento y práctica deberían ser interactivos; producir económicamente no debería exigir repetir cientos de veces el mismo minijuego.</p><p>Un proceso completado manualmente en un puesto/sesión puede establecer un patrón de producción temporal o local al puesto. Con suficiente habilidad, ilustrativamente alrededor de <strong>30–50 según la profesión</strong>, el personaje puede repetir procedimientos conocidos por lotes. No es un desbloqueo permanente universal de receta ni un umbral aceptado.</p><p>La producción por lotes consume tiempo y materiales reales y exige que el personaje permanezca en el puesto o suficientemente involucrado. Movimiento, combate, muerte o pérdida del puesto pueden interrumpirla. No debe ser instantánea ni una gran vía abusiva de aumento de habilidad. Conservar un rango razonable de consistencia de calidad; no destruir unidades individuales aleatoriamente sin causa justificada.</p><p>Una habilidad mayor mejora tamaño del lote, consistencia, eficiencia y acceso a procedimientos más complejos. Práctica/descubrimiento y producción pueden ser modos conceptuales distintos. Duración del patrón, participación, propiedad de materiales interrumpidos, resultados parciales, costes y reglas de aumento necesitan diseño explícito antes de implementarse.</p><h2 id="commissions-reputation-and-economy" tabindex="-1">Encargos, reputación y economía <a class="header-anchor" href="#commissions-reputation-and-economy" aria-label="Enlace permanente a &quot;Encargos, reputación y economía&quot;">​</a></h2><p>Reemplazar el espíritu de los Bulk Order Deeds por encargos/contratos funcionales. Posibles emisores: gremios artesanales, familias, clanes, facciones, grupos militares, ciudades, nobles, comerciantes y eventualmente jugadores.</p><p>Un encargo debería especificar necesidades en lugar de exigir una receta exacta cuando sea posible. Por ejemplo, <strong>20 corazas de infantería</strong> podrían requerir peso medio o menor, alta resistencia al trauma contundente, durabilidad mínima y aptitud para expediciones. Este ejemplo no es un objeto ni una fórmula de armadura definitivos.</p><p>Pago y reputación consideran requisitos cumplidos, materiales, factura, consistencia, especialización relevante y límites adecuados de coste/peso. La reputación debería ser multidimensional e idealmente surgir de productos reales y uso prolongado, no de una sola puntuación de estrellas. Un personaje podría ser conocido por armas de campaña duraderas, placas ligeras, mazas de alto trauma, prendas lujosas, cerraduras fiables o arcos de guerra eficientes. Marcas de fabricante y procedencia pueden apoyar esa historia.</p><p>Los encargos de jugadores son un objetivo futuro. Adjudicación de contratos, atribución a largo plazo, abuso de reputación, custodia del pago y resolución de disputas siguen sin resolverse; aquí no se selecciona un servicio económico ni un diseño de pagos automáticos.</p><h2 id="performance-abstraction-and-authority" tabindex="-1">Rendimiento, abstracción y autoridad <a class="header-anchor" href="#performance-abstraction-and-authority" aria-label="Enlace permanente a &quot;Rendimiento, abstracción y autoridad&quot;">​</a></h2><p><strong>Simulación compleja por debajo, decisiones simples por encima. Preferir estado persistente compacto + comportamiento derivado.</strong> Una variable debería sobrevivir a la abstracción solo si crea decisiones significativas. Evitar decenas de floats almacenados por objeto, actualizaciones continuas de objetos pasivos y detalle sin valor para el jugador. Preferir estado ambiental compartido/regional, actualizaciones por eventos, simulación diferida y propiedades derivadas de material, especie, calidad, tratamiento o semilla.</p><p>Son restricciones de diseño, no un esquema ni algoritmo de implementación seleccionados. Seguir la propuesta de arquitectura del mundo vivo, límites de autoridad y reglas de persistencia/ciclo de vida al diseñar la implementación por separado. Diarios por personaje, patrones de producción y procedencia de objetos necesitan decisiones explícitas de guardado/ciclo de vida; este documento no autoriza migraciones de esquemas.</p><table tabindex="0"><thead><tr><th>Límite</th><th>Ejemplo profesional</th></tr></thead><tbody><tr><td>USER INTENT</td><td>Colocar un ingrediente, intentar una operación de forja, talar un árbol o solicitar un lote</td></tr><tr><td>AUTHORITATIVE SERVER STATE</td><td>Validar conocimiento, habilidad, recursos, propiedad, tiempos, interrupción y resultado real</td></tr><tr><td>SYNCHRONIZED STATE</td><td>Estado aprobado del puesto, progreso, objetos resultantes y divulgaciones permitidas de conocimiento</td></tr><tr><td>CLIENT PRESENTATION</td><td>Gump del puesto, respuesta al arrastrar/soltar, animación, sonido e indicios cualitativos</td></tr></tbody></table><p>Arrastrar/soltar y animación no deciden finalización, calidad del objeto, colisión del mundo ni consumo de recursos. Esto conserva la autoridad existente del servidor con estado Aceptado sin asignar nuevos paquetes, clases ni recursos del cliente.</p><h2 id="profession-specifications" tabindex="-1">Especificaciones de profesiones <a class="header-anchor" href="#profession-specifications" aria-label="Enlace permanente a &quot;Especificaciones de profesiones&quot;">​</a></h2><ul><li><a href="/Syrolands-Public/es/game-design/professions/cooking.html">Cooking</a></li><li><a href="/Syrolands-Public/es/game-design/professions/alchemy.html">Alchemy</a></li><li><a href="/Syrolands-Public/es/game-design/professions/mining.html">Mining</a></li><li><a href="/Syrolands-Public/es/game-design/professions/blacksmithing.html">Blacksmithing</a></li><li><a href="/Syrolands-Public/es/game-design/professions/tailoring.html">Tailoring</a></li><li><a href="/Syrolands-Public/es/game-design/professions/lumberjacking.html">Lumberjacking</a></li><li><a href="/Syrolands-Public/es/game-design/professions/carpentry.html">Carpentry</a></li><li><a href="/Syrolands-Public/es/game-design/professions/tinkering.html">Tinkering</a></li><li><a href="/Syrolands-Public/es/game-design/professions/inscription.html">Inscription</a></li></ul><h2 id="open-questions-and-reconciliation-required" tabindex="-1">Preguntas abiertas y conciliación necesaria <a class="header-anchor" href="#open-questions-and-reconciliation-required" aria-label="Enlace permanente a &quot;Preguntas abiertas y conciliación necesaria&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Área</th><th>Fuente existente y límite de conciliación</th></tr></thead><tbody><tr><td>Listado de habilidades / Bowcraft</td><td><a href="/Syrolands-Public/es/game-design/skills-and-knowledge.html">Habilidades y conocimiento</a> resume funciones, no es un listado exhaustivo conciliado. No se elimina Bowcraft independiente, convierten ID, migran personajes ni compensan entrenamientos. Bowmaking es una dirección técnica firme con estado Propuesto pendiente de esa conciliación.</td></tr><tr><td>Disciplinas adyacentes</td><td><a href="/Syrolands-Public/es/game-design/living-world.html#knowledge-professions-and-traces">Mundo vivo</a> planteó antes Forestry, Engineering y Geology como posibles nuevas habilidades. Este lote ubica esa pericia en Lumberjacking, Tinkering y Mining. No inferir tres habilidades nuevas; conciliar explícitamente el listado final.</td></tr><tr><td>Progresión y magia</td><td>La <a href="/Syrolands-Public/es/game-design/magic.html#use-based-gain-and-structured-teaching">progresión mágica</a> incluye bloques ilustrativos de entrenamiento +5 y ritmo del primer día; su modelo de fallo de hechizos cerca del límite de capacidad no se sustituye silenciosamente por trabajo artesanal simple consistente. Conciliar ritmo global, competencia inicial y dificultad específica de profesión antes de elegir fórmulas. Magery Mastery y Concentration no son automáticamente habilidades nuevas con límite.</td></tr><tr><td>Anatomy y Healing</td><td>Conservar la <a href="/Syrolands-Public/es/game-design/skills-and-knowledge.html">regla aprobada de Anatomy de Stage 2A</a>. La recolección material, alivio del dolor, sangrado y curación con estado Propuesto no alteran esa regla ni establecen lesiones implementadas. La coordinación con Healing sigue abierta.</td></tr><tr><td>Equipo y pérdida</td><td><a href="/Syrolands-Public/es/game-design/equipment-and-loot.html">Equipo y botín</a> favorece equipo horizontal reemplazable y pérdidas significativas. Los masterworks/conjuntos raros deben ajustarse; los conjuntos sagrados/resonantes no aprueban conservación de Sacred Item, seguros amplios ni protección de libros de hechizos.</td></tr><tr><td>Fórmulas de combate</td><td><a href="/Syrolands-Public/es/game-design/combat/damage.html">Daño y Local Trauma</a> define la política experimental de residual ×2. Nuevas dimensiones de calidad, umbrales de armadura, desgaste funcional y rasgos no pueden cambiarla silenciosamente. Ver <a href="/Syrolands-Public/es/game-design/items/itemization-and-craft-quality.html#open-questions-and-reconciliation">conciliación de calidad</a>.</td></tr><tr><td>Mundo modificable</td><td>La <a href="/Syrolands-Public/es/game-design/living-world.html#terrain-and-authored-geology">geología diseñada</a> limita excavaciones; este lote no autoriza excavar sin restricciones. Protección, recuperación, puentes, espacio ocupado por árboles caídos, daño estructural y acceso a viviendas siguen sin resolverse; el alcance del primer prototipo de árboles/hierba no cambia.</td></tr></tbody></table><p>Las <a href="/Syrolands-Public/es/game-design/characters/skills-and-skillcap.html#reconciliation-and-open-questions">preguntas compartidas de habilidades/enseñanza</a>, <a href="/Syrolands-Public/es/game-design/characters/character-creation.html#open-questions">preguntas de creación</a> y <a href="/Syrolands-Public/es/game-design/characters/techniques-and-specialization.html#open-questions">custodia de técnicas</a> se centralizan en Personajes. Persisten preguntas específicas de profesiones: representación de diarios; propiedad de puestos y cancelación de lotes; manipulación de reputación; verificación de contratos; sumideros económicos y balance de producción. Son brechas identificadas documentalmente, no mecánicas añadidas.</p><h2 id="related-decisions-experiments-and-evidence" tabindex="-1">Decisiones, experimentos y evidencias relacionados <a class="header-anchor" href="#related-decisions-experiments-and-evidence" aria-label="Enlace permanente a &quot;Decisiones, experimentos y evidencias relacionados&quot;">​</a></h2><p>La autoridad del servidor con estado Aceptado, la decisión Lab-first, el experimento existente de combate localizado y la evidencia del segmento actual conservan sus alcances. No se ha ejecutado ningún experimento profesional ni se declara ningún ADR nuevo Aceptado. La propuesta no establece gameplay implementado.</p>',43)])])}const g=a(o,[["render",r]]);export{u as __pageData,g as default};
